            # that contains this marker.
            best = (1, 1, sr, sc)
            for top in range(sr, -1, -1):
                for bottom in range(sr, h):
                    if any(grid[r][sc] not in (1, color)
                           for r in range(top, bottom + 1)):
                        break
                    left = sc
