                                           for r in range(top, bottom + 1)):
                        left -= 1
                    right = sc
                    while right + 1 < w and all(grid[r][right + 1] == 1
                                                for r in range(top, bottom + 1)):
                        right += 1
                    area = (bottom - top + 1) * (right - left + 1)
                    if area > best[0] * best[1]:
                        best = (bottom - top + 1, right - left + 1, top, left)

            bh, bw, _, _ = best
            # Color matching solid rectangles elsewhere as well.
            for r in range(h - bh + 1):
                for c in range(w - bw + 1):
